sys_script.script:
(function executeRule(current, previous) {
    var status = (current.application_status + "").toLowerCase();
    var prevStatus = (previous.application_status + "").toLowerCase();
    if (status === "approved" && prevStatus !== "approved") {
        var prog = current.scholarship_program.getRefRecord();
        if (!prog.isValidRecord()) return;
        var seats = parseInt(prog.available_seats, 10);
        if (isNaN(seats) || seats <= 0) {
            gs.addErrorMessage("Cannot approve application: No available seats remaining for this program.");
            current.setAbortAction(true);
        } else {
            prog.available_seats = seats - 1;
            prog.update();
        }
    }
})(current, previous);
